import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"Ceph Performance Meeting 2020-06-11","description":"","frontmatter":{"title":"Ceph Performance Meeting 2020-06-11","date":"2020-06-11T00:00:00.000Z","updated":"2020-06-12T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH 算法","高可用性","可伸缩性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Performance_Meeting_2020-06-11.md","filePath":"posts/2020/Ceph_Performance_Meeting_2020-06-11.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Performance_Meeting_2020-06-11.md"};function r(n,e,s,p,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h4><p>本次Ceph性能会议主要讨论了项目的最新进展，包括新提交的Pull Request（PR）、已关闭的PR、更新的PR以及一些重要的技术讨论。会议还涉及了开发冻结前的准备工作。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新PR介绍</strong></p><ul><li>提交了一个新的PR，旨在为Blue Store添加阻塞跟踪功能。目前尚未有人审查此PR，建议关注。</li></ul></li><li><p><strong>已关闭PR</strong></p><ul><li>一个关于ARM架构新测试的旧PR因长时间未更新被关闭。</li></ul></li><li><p><strong>更新PR</strong></p><ul><li>多个PR被更新，包括： <ul><li>Adam的PR，旨在防止RocksDB中的巨大写日志大小，涉及大量讨论。</li><li>Ma Jinping的PR，关于启用RocksDB的流水线写入功能，尽管测试未见性能提升。</li><li>改进mempool跟踪的PR，将数据结构分解为更具体的部分。</li><li>基准测试buffer list encode和decode的PR，讨论是否应将此类测试移至外部。</li></ul></li></ul></li><li><p><strong>重要技术讨论</strong></p><ul><li>讨论了Igor的PR，旨在修复一个罕见的段错误。</li><li>讨论了避免双重缓存的PR，需要进行显著的重构。</li><li>讨论了mempool的使用和内存管理，特别是关于重新分配内存到mempool的问题。</li><li>讨论了优先级缓存管理器（PCM）的改进，希望通过更详细的内存使用统计来优化缓存管理。</li></ul></li><li><p><strong>其他事项</strong></p><ul><li>继续进行IO500测试，特别是关于预分割和预导出目录碎片的优化工作。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要对新PR进行审查和测试。</li><li>需要进一步讨论和优化mempool的使用和内存管理。</li><li>需要继续推进避免双重缓存的PR。</li><li>优化IO500测试，特别是预分割和预导出目录碎片的性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>审查和测试新PR。</li><li>优化IO500测试。</li><li>完成重要PR的合并和优化工作。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论了所有议题后结束，感谢所有参与者的贡献。下次会议再见。</p>',11)])])}const c=l(o,[["render",r]]);export{P as __pageData,c as default};
